tanh_ext = load_inline(
    name="tanh_ext",
    cpp_sources=cpp_source,
    cuda_sources=tanh_source,
    functions=["tanh_cuda"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.tanh_ext = tanh_ext
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.tanh_ext.tanh_cuda(x)
